package com.quizapp.model;
import java.time.Instant;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;import org.springframework.data.mongodb.core.index.Indexed;
@Document("users") public class User { @Id private String id; @Indexed(unique=true) private String email; private String name,passwordHash,role,accountStatus,hostApprovalStatus,rejectionReason,profilePhoto; private Boolean quizPostingEnabled = true; private Instant createdAt=Instant.now(); public String getId(){return id;}public void setId(String v){id=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPasswordHash(){return passwordHash;}public void setPasswordHash(String v){passwordHash=v;}public String getRole(){return role;}public void setRole(String v){role=v;}public String getAccountStatus(){return accountStatus;}public void setAccountStatus(String v){accountStatus=v;}public String getHostApprovalStatus(){return hostApprovalStatus;}public void setHostApprovalStatus(String v){hostApprovalStatus=v;}public String getRejectionReason(){return rejectionReason;}public void setRejectionReason(String v){rejectionReason=v;}public String getProfilePhoto(){return profilePhoto;}public void setProfilePhoto(String v){profilePhoto=v;}public boolean isQuizPostingEnabled(){return quizPostingEnabled == null || quizPostingEnabled;} public void setQuizPostingEnabled(boolean v){quizPostingEnabled=v;} public Instant getCreatedAt(){return createdAt;} }
